fn partition_even(values: &mut [i32]) -> usize {
    let mut boundary = 0;
    for i in 0..values.len() {
        if values[i] % 2 == 0 { values.swap(boundary, i); boundary += 1; }
    }
    boundary
}

fn main() {
    let result = { let mut values=vec![1,3]; partition_even(&mut values).to_string() };
    println!("{result}");
}

